      <h1 class="almanac-title almanac-title-sm">${i()?'\u6BCF\u4E00\u4E2A\u627F\u8BFA<br/>\u90FD\u662F\u4E00\u4E2A<span class="almanac-title-accent">\u95E8\u3002</span>':'Every promise<br/>is a <span class="almanac-title-accent">gate.</span>'}</h1>
